import express from 'express';
import mysql from 'mysql2/promise';
import path from 'path';
import { fileURLToPath } from 'url';
import bodyParser from 'body-parser';
import cors from 'cors';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const PORT = process.env.PORT || 80;

app.use(cors());
app.use(bodyParser.json());
app.use(express.static(path.join(__dirname, 'dist')));

// 数据库连接配置（平台自身元数据库）
const dbConfig = {
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '123456',
  database: process.env.DB_NAME || 'tiangong_db',
  port: parseInt(process.env.DB_PORT || '3306'),
  connectTimeout: 5000
};

let pool = null;

async function initDB() {
  try {
    pool = mysql.createPool(dbConfig);
    // 立即尝试连一下确认配置正确
    await pool.query('SELECT 1');
    console.log(`Connected to Meta-MySQL at ${dbConfig.host}`);

    await pool.query(`
      CREATE TABLE IF NOT EXISTS data_sources (
        id VARCHAR(50) PRIMARY KEY,
        name VARCHAR(100) NOT NULL,
        type VARCHAR(20),
        host VARCHAR(100),
        port INT,
        database_name VARCHAR(100),
        username VARCHAR(100),
        password VARCHAR(100),
        status VARCHAR(20) DEFAULT 'online',
        last_scanned VARCHAR(50)
      )
    `);
  } catch (err) {
    console.error('Meta Database initialization failed:', err.message);
    // 不要让 pool 保持为 null 以外的东西，如果彻底失败则置空
    pool = null;
  }
}

// 检查数据库池是否就绪的中间件
const checkDbReady = (req, res, next) => {
  if (!pool) {
    return res.status(503).json({ success: false, error: '系统元数据库未连接，请检查后端 DB_HOST 等环境变量配置。' });
  }
  next();
};

// API: 真实测试数据源连接
app.post('/api/sources/test', async (req, res) => {
  const { type, host, port, username, password, database } = req.body;

  if (type !== 'mysql') {
    return res.status(400).json({ success: false, error: `目前仅支持 MySQL 类型的数据源在线测试，${type} 正在开发中。` });
  }

  try {
    const connection = await mysql.createConnection({
      host,
      port: parseInt(port || '3306'),
      user: username,
      password,
      database,
      connectTimeout: 5000
    });

    await connection.query('SELECT 1');
    await connection.end();

    res.json({ success: true, message: '连接成功' });
  } catch (err) {
    console.error('Test Connection Failed:', err.message);
    res.status(500).json({ 
      success: false, 
      error: err.message,
      code: err.code 
    });
  }
});

// API: 获取数据源
app.get('/api/sources', checkDbReady, async (req, res) => {
  try {
    const [rows] = await pool.query('SELECT * FROM data_sources');
    const sources = rows.map(r => ({
      id: r.id,
      name: r.name,
      type: r.type,
      host: r.host,
      port: r.port,
      database: r.database_name,
      username: r.username,
      status: r.status,
      lastScanned: r.last_scanned
    }));
    res.json(sources);
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// API: 新增/更新数据源
app.post('/api/sources', checkDbReady, async (req, res) => {
  const s = req.body;
  try {
    await pool.query(
      `INSERT INTO data_sources (id, name, type, host, port, database_name, username, password, status, last_scanned) 
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?) 
       ON DUPLICATE KEY UPDATE name=?, type=?, host=?, port=?, database_name=?, username=?, password=?, status=?`,
      [s.id, s.name, s.type, s.host, s.port, s.database, s.username, s.password, s.status || 'online', s.lastScanned || '',
       s.name, s.type, s.host, s.port, s.database, s.username, s.password, s.status || 'online']
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// API: 删除数据源
app.delete('/api/sources/:id', checkDbReady, async (req, res) => {
  try {
    await pool.query('DELETE FROM data_sources WHERE id = ?', [req.params.id]);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

app.listen(PORT, () => {
  initDB();
  console.log(`Tiangong Platform Server running on port ${PORT}`);
});

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, Database, Shield, Activity, Settings, 
  Search, Plus, RefreshCw, Trash2, CheckCircle, XCircle, 
  Database as DbIcon, ShieldCheck, AlertTriangle, Play, X,
  ArrowUpRight, BarChart3, HardDrive, Layers, Sparkles, ChevronRight,
  GitBranch, Clock, FileCode, Wifi
} from 'lucide-react';
import { DataSource, SensitiveRule, InspectionRecord, DatabaseType } from '../../types';
import { INITIAL_DATA_SOURCES } from '../../constants';
import DataSourceModal from './DataSourceModal';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area, BarChart, Bar } from 'recharts';

const DatabaseManager: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'sources' | 'sensitive' | 'inspection' | 'profile'>('dashboard');
  const [sources, setSources] = useState<DataSource[]>([]);
  const [loading, setLoading] = useState(true);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [editingSource, setEditingSource] = useState<DataSource | null>(null);
  const [sourceToDelete, setSourceToDelete] = useState<string | null>(null);
  const [testResult, setTestResult] = useState<Record<string, { status: 'success' | 'error' | 'loading' | null, msg?: string }>>({});

  const safeFetchJson = async (url: string, options?: RequestInit) => {
    const res = await fetch(url, options);
    const text = await res.text();
    try {
      return JSON.parse(text);
    } catch (e) {
      console.error(`Failed to parse JSON from ${url}. Raw text content:`, text);
      throw new Error(`响应格式错误 (非JSON): ${text.slice(0, 50)}...`);
    }
  };

  const fetchSources = async () => {
    try {
      setLoading(true);
      const data = await safeFetchJson('/api/sources');
      setSources(Array.isArray(data) ? data : []);
    } catch (err: any) {
      console.error('Fetch error:', err.message);
      setSources(INITIAL_DATA_SOURCES);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSources();
  }, []);

  const handleTestConnection = async (source: DataSource) => {
    const id = source.id;
    setTestResult(prev => ({ ...prev, [id]: { status: 'loading' } }));

    try {
      const data = await safeFetchJson('/api/sources/test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(source)
      });

      if (data.success) {
        setTestResult(prev => ({ ...prev, [id]: { status: 'success' } }));
      } else {
        setTestResult(prev => ({ ...prev, [id]: { status: 'error', msg: data.error } }));
      }
    } catch (err: any) {
      setTestResult(prev => ({ ...prev, [id]: { status: 'error', msg: err.message || '网络错误' } }));
    }

    setTimeout(() => {
      setTestResult(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }, 5000);
  };

  const handleSaveSource = async (data: Partial<DataSource>) => {
    const payload = editingSource 
      ? { ...editingSource, ...data } 
      : { ...data, id: Date.now().toString(), status: 'online' };

